#!/usr/bin/env python3
"""Author the lightweight sixteen-patch catalogue and matching C table."""
from pathlib import Path
import json
# Legacy indices 0..2 and their exact synthesis settings are intentionally stable.
rows=[
 ('wood','Wood','Original',16500,27000,35000,16000,0,1800,24,.28,0,0,6,'Mellow original plucked string.'),
 ('wire','Wire','Original',23000,46000,43000,16000,0,1800,24,.28,0,0,6,'Bright original plucked string.'),
 ('glow','Glow','Original',34000,37000,49000,16000,0,2400,24,.28,0,0,6,'Synthetic original string colour.'),
 ('nylon','Nylon Acoustic','Guitar',13500,34500,43000,16500,0,2450,32,.34,0,0,6,'Warm fingerpicked attack, clear upper strings and a fuller ringing body.'),
 ('steel','Steel Acoustic','Guitar',16500,45500,38000,16000,0,2300,24,.26,0,0,6,'Bright picked strings with a warmer, naturally damped tail.'),
 ('jumbo','Jumbo Acoustic','Guitar',11000,38500,49000,19500,0,2750,32,.29,0,0,6,'Rounder low end and an open ringing tail.'),
 ('palm','Palm Muted','Guitar',16000,39500,18000,12500,0,620,24,.34,0,0,6,'Short, damped attacks for tight rhythmic playing.'),
 ('clean','Clean Electric','Guitar',18000,46500,45500,20000,0,2450,28,.27,0,0,6,'Clean electric-like picked string.'),
 ('jazz-guitar','Round Jazz Guitar','Guitar',13500,28500,39500,22500,0,2050,48,.34,0,0,6,'Soft, dark attack for round jazz chords.'),
 ('crunch','Crunch Electric','Guitar',19000,45500,39000,13000,0,2100,28,.23,2.8,0,6,'Picked strings with gentle per-voice saturation.'),
 ('heavy','Heavy Electric','Guitar',21000,49000,36000,10500,0,1900,28,.18,7.0,0,6,'Harder saturated attack with controlled decay.'),
 ('harp','Harp','Other',4500,43500,54000,23500,0,2900,40,.26,0,12,6,'Clear ringing plucks across six chord parts; intensity stays clean.'),
 ('violin','Violin','Other',12000,30000,42000,20000,0,2200,4500,.23,0,12,6,'Clean sustained violin-style harmonics with a smooth swell; intensity adds no distortion.'),
 ('cello','Pizzicato Cello','Other',9000,31500,43000,24000,0,2300,100,.34,0,-12,6,'Six plucked chord parts in a low cello register.'),
 ('bass','Electric Bass','Other',10500,31500,33000,14500,0,1700,40,.32,.6,-12,6,'Six chord parts in a bass register.'),
 ('dulcimer','Dulcimer','Other',36500,51000,39000,8500,0,1850,20,.21,0,12,6,'Bright hammered-string-inspired colour.')]
patches=[]
for id,name,family,st,br,da,pos,bow,ms,attack,gain,drive,shift,parts,description in rows:
 mapping=([2,3,4,5,2,3] if id in ('violin','cello') else [0,1,2,3,0,1]) if parts==4 else [0,1,2,3,4,5]
 patches.append(dict(id=id,name=name,family=family,structure=st,brightness=br,damping=da,position=pos,bow=bow,durationMs=ms,attackSamples=attack,gain=gain,drive=drive,octaveOffset=shift,parts=parts,mapping=mapping,description=description))
Path('web/instruments.json').write_text(json.dumps({'schemaVersion':1,'instruments':patches},indent=2)+'\n')
def fl(x):return f'{float(x):.6f}f'
lines=['// Generated by scripts/create-instrument-library.py; preserve original indices 0..2.', '#define GM_TONES 16', 'typedef struct { const char *name; int structure, brightness, damping, position, bow, ms, attack; float gain, drive; int shift, parts; int map[6]; } gm_patch;', 'static const gm_patch gm_patches[GM_TONES] = {']
for p in patches:
 fields=[json.dumps(p['name'])]+[str(p[k]) for k in ['structure','brightness','damping','position','bow','durationMs','attackSamples']]+[fl(p['gain']),fl(p['drive'])]+[str(p[k]) for k in ['octaveOffset','parts']]+['{'+','.join(map(str,p['mapping']))+'}']
 lines.append('    {'+', '.join(fields)+'},')
lines.append('};')
Path('dsp/instruments.h').write_text('\n'.join(lines)+'\n')
